CREATE TABLE "hutang_awal" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "hutang_awal_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"nomor" varchar(30) NOT NULL,
	"tanggal_operasional" date NOT NULL,
	"id_pemasok" bigint NOT NULL,
	"id_pengguna" bigint NOT NULL,
	"no_faktur_lama" varchar(50),
	"tanggal_faktur" date,
	"total" bigint NOT NULL,
	"total_dibayar" bigint DEFAULT 0 NOT NULL,
	"sisa_hutang" bigint GENERATED ALWAYS AS (total - total_dibayar) STORED,
	"status_hutang" varchar(12) DEFAULT 'BELUM_LUNAS' NOT NULL,
	"tanggal_jatuh_tempo" date NOT NULL,
	"catatan" varchar(255),
	"dibuat_pada" timestamp with time zone DEFAULT now() NOT NULL,
	"diubah_pada" timestamp with time zone,
	CONSTRAINT "hutang_awal_nomor_key" UNIQUE("nomor"),
	CONSTRAINT "chk_hutang_awal_total" CHECK (total > 0 and total_dibayar >= 0 and total_dibayar <= total),
	CONSTRAINT "chk_hutang_awal_status" CHECK (status_hutang in ('TIDAK_ADA','BELUM_LUNAS','SEBAGIAN','LUNAS'))
);
